import java.io.*;

public class Main {
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int read() throws IOException {
        if (ptr == len) {
            len = System.in.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) return -1;
        }
        return BUF[ptr++];
    }

    static String next() throws IOException {
        int c = read();
        while (c != -1 && c <= ' ') c = read();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = read();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        String s = next();
        char previous = 0;
        long answer = 0;
        // Only changes between consecutive fixed characters are unavoidable.
        for (int i = 0; i < s.length(); i++) {
            char c = s.charAt(i);
            if (c == '?') continue;
            if (previous != 0 && previous != c) answer++;
            previous = c;
        }
        System.out.println(answer);
    }
}

