import (
	"bufio"
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

func next() string {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return string(data[start:pos])
}

